<script setup>
import {Button,Cell,Progress,Tag} from 'vant';
import 'vant/es/button/style';import 'vant/es/cell/style';import 'vant/es/progress/style';import 'vant/es/tag/style';
defineProps({model:{type:Object,required:true}});
const progressLevel=value=>!Number.isFinite(value)?undefined:value>=90?'mastered':value>=60?'growing':value>=30?'developing':value>0?'started':'none';
</script>
<template>
 <section class="student-catalog" :class="model.kind==='catalog'?'catalog-shell':''" :data-student-page="model.kind">
  <template v-if="model.kind==='catalog'">
   <nav class="page-nav" aria-label="页面导航"><Button tag="a" href="index.html" class="back-link" icon="arrow-left">返回选科</Button><span class="mini-brand"><img class="brand-logo" :src="'brand-logo.webp'" alt="" width="32" height="32">逆流</span></nav>
   <header class="catalog-heading"><div><p class="eyebrow">八年级 · {{model.edition}}</p><h1>{{model.subjectName}}<span>{{model.tagline}}</span></h1></div><div class="subject-stamp" aria-hidden="true">{{model.subject==='physics'?'v = s/t':model.subject==='math'?'x²':'Aa'}}</div></header>
   <div class="catalog-actions"><nav class="term-switch" aria-label="选择学期"><Button v-for="term in model.terms" :key="term.key" tag="a" :href="term.href" :aria-current="term.key===model.term?'page':undefined">{{term.name}}<span>{{term.key==='upper'?'上学期':'下学期'}}</span></Button></nav><Button tag="a" :href="model.resources.href" class="resources-link">{{model.resources.label}} <span aria-hidden="true">→</span></Button></div>
   <nav v-if="model.animationHref" class="catalog-tools" aria-label="英语学习工具"><Button tag="a" :href="model.animationHref" class="english-animation-button">动画记单词 →</Button></nav>
   <p v-if="model.notice" class="verification-note" role="note">ⓘ {{model.notice}}</p>
   <section class="unit-section" aria-labelledby="student-unit-title"><div class="list-heading"><h2 id="student-unit-title">{{model.termName}}<span> / {{model.subject==='english'?'单元':'章节'}}目录</span></h2><p>{{model.units.length}} {{model.verified?(model.subject==='english'?'个单元':'章'):'个预留单元'}}<span v-if="model.units.some(u=>u.available)" class="available-count"> · {{model.units.filter(u=>u.available).length}} {{model.subject==='english'?'个':'章'}}可学习</span></p></div>
    <ol class="unit-list student-unit-list"><li v-for="unit in model.units" :key="unit.id" class="student-unit" :data-unit="unit.id">
     <div class="unit-row" :class="{'is-ready':unit.available}" :data-mastery-level="progressLevel(unit.mastery)"><span class="unit-number" aria-hidden="true">{{String(unit.number).padStart(2,'0')}}</span><div class="unit-copy"><span class="unit-label">{{unit.label}}</span><div class="unit-title"><h3><Cell tag="a" :href="unit.href" :title="unit.title" :aria-label="unit.label+' '+unit.title+'，'+(unit.state||'可学习')"/></h3></div><p>{{unit.summary}}</p><div v-if="unit.summaryHref" class="unit-actions"><Button tag="a" :href="unit.summaryHref" class="unit-reward-trigger">单元总结</Button></div><div v-if="unit.available&&Number.isFinite(unit.mastery)&&unit.mastery>0" class="unit-progress student-mastery" :data-mastery-level="progressLevel(unit.mastery)" role="progressbar" :aria-label="unit.title+'掌握度'" :aria-valuenow="unit.mastery" aria-valuemin="0" aria-valuemax="100"><span>{{unit.mastery}}%</span><Progress :percentage="unit.mastery" :show-pivot="false" stroke-width="7" color="var(--mastery-color, var(--accent, #557b3c))" track-color="#dfe8d5"/></div><p v-if="unit.masteryError" class="student-record-error" role="status">{{unit.masteryError}}</p></div><span v-if="!unit.available" class="unit-state">{{unit.state}}</span></div>
    </li></ol>
   </section><p class="catalog-footnote">{{model.footnote}}</p>
  </template>
  <template v-else-if="model.kind==='pending'">
   <nav class="student-pending-nav" aria-label="页面导航"><Button tag="a" :href="model.backHref" class="back-link" icon="arrow-left">{{model.subjectName}}目录</Button><Button tag="a" href="index.html" class="back-link">选择课程</Button></nav>
   <main class="pending-shell"><div class="pending-emblem" aria-hidden="true">{{model.subjectName==='英语'?'Aa':'∠'}}</div><p class="eyebrow">{{model.termName}} · {{model.label}}</p><h1>{{model.title}}</h1><Tag class="pending-state">{{model.state}}</Tag><p class="pending-description">{{model.description}}</p><section v-if="model.outline?.length" class="outline"><h2>本单元内容</h2><ol><li v-for="(topic,index) in model.outline" :key="index"><span>{{String(index+1).padStart(2,'0')}}</span>{{topic}}</li></ol></section><div class="student-pending-actions"><Button tag="a" :href="model.backHref" class="primary-link">返回{{model.subjectName}}目录</Button><Button v-if="model.graphHref" tag="a" :href="model.graphHref" class="back-link">图谱 · 诊断</Button></div></main>
  </template>
  <div v-else class="route-error"><h1>{{model.title}}</h1><p role="status">{{model.kind==='redirect'?'正在进入课堂…':model.description}}</p><Button tag="a" :href="model.href||model.backHref||'index.html'" class="primary-link">{{model.kind==='redirect'?'继续进入课堂':'返回选科'}}</Button></div>
 </section>
</template>
<style scoped>
.student-catalog{font:inherit;color:inherit}.student-catalog :deep(.van-button){font:inherit;box-shadow:none;text-decoration:none;height:auto}.page-nav>.van-button,.student-pending-nav>.van-button{background:transparent;border:0;padding:0;color:var(--ui-muted);font-size:14px;min-height:44px}.term-switch>.van-button{border:0;background:transparent;height:auto;min-height:44px}.term-switch>.van-button[aria-current]{background:#fff;color:var(--ui-ink)}.term-switch :deep(.van-button__text){display:flex;align-items:center;gap:12px}.term-switch :deep(.van-button__text>span){font-size:11px;opacity:.8}.resources-link.van-button{min-height:56px;border:1px solid var(--ui-line);border-radius:10px;color:var(--ui-accent);background:var(--ui-surface,#fff);font-size:14px;padding:12px 16px}.resources-link :deep(.van-button__text){display:flex;gap:14px}.english-animation-button.van-button{font-size:13px;padding:10px 17px;border:1px solid #839c72;border-radius:11px;background:#fffdf5;color:#45673f;min-height:44px}.student-unit .van-cell{background:transparent;padding:0;line-height:inherit;color:inherit;font:inherit;overflow:visible}.student-unit :deep(.van-cell__title){font:inherit}.student-unit .van-cell:after{display:none}.unit-reward-trigger.van-button{background:var(--ui-soft);color:var(--ui-accent);height:auto;box-shadow:none}.student-mastery{display:flex;align-items:center;gap:10px;font-size:12px;color:var(--ui-muted)}.student-mastery :deep(.van-progress){flex:1;background:var(--ui-line)}.student-record-error{grid-column:1/-1!important;color:#936632!important}.student-pending-nav{display:flex;justify-content:space-between;max-width:1160px;margin:auto;padding:20px 30px}.student-pending-actions{display:flex;align-items:center;justify-content:center;gap:18px;flex-wrap:wrap}.primary-link.van-button{background:var(--ui-accent);color:#fff;border:0}.pending-state{background:var(--ui-soft);color:var(--ui-muted)}
@media(max-width:600px){.term-switch :deep(.van-button__text>span){display:none}.resources-link.van-button{min-height:53px;padding:11px 12px;font-size:13px}.student-pending-nav{padding:16px 18px}}
.student-catalog .term-switch :deep(.van-button__text){font-size:15px;line-height:1.7;opacity:1}.student-catalog .unit-actions .unit-reward-trigger{font:400 11px/normal "Segoe UI","Microsoft YaHei",system-ui,sans-serif;min-height:0;height:auto;padding:5px 9px;background:#ecf4e1}.student-catalog .resources-link{border-color:var(--ui-control);border-radius:8px;color:var(--ui-ink)}
@media(max-width:600px){.student-catalog .term-switch :deep(.van-button__text){display:flex;font-size:14px}.student-catalog .unit-actions .unit-reward-trigger{min-height:44px;font-size:12px;padding:8px}}
.student-catalog .student-mastery{display:grid;grid-template-columns:minmax(0,1fr);gap:6px;font-size:13px;color:var(--mastery-color,var(--ui-muted));font-variant-numeric:tabular-nums}.student-catalog .student-mastery :deep(.van-progress){width:100%;min-width:0;border-radius:8px}.student-catalog .unit-row[data-mastery-level=none]{--mastery-color:#6b7562;--mastery-soft:#f0f2eb;--mastery-tint:#fbfcf9;background:var(--mastery-tint)}.student-catalog .unit-row[data-mastery-level=none] .unit-number{color:var(--mastery-color);background:var(--mastery-soft)}.student-catalog .unit-row[data-mastery-level] .unit-reward-trigger{color:var(--mastery-color);background:var(--mastery-soft)}
</style>
